[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. Always free." />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <link href="https://cdn.jsdelivr.net/npm/remixicon@4.5.0/fonts/remixicon.css" rel="stylesheet" />
  <style>
    /* ── Reset & Base ── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      font-size: 16px;
      color: #1a1a2e;
      background: #fff;
      line-height: 1.6;
      overflow-x: hidden;
    }
    img { max-width: 100%; display: block; }
    a { text-decoration: none; color: inherit; }
    button { cursor: pointer; font-family: inherit; border: none; outline: none; }

    /* ── Design Tokens ── */
    :root {
      --navy:     #1B1464;
      --navy-mid: #2a1f8f;
      --blue:     #2563EB;
      --blue-lt:  #3B82F6;
      --yellow:   #FFD930;
      --yellow-dk:#E6C300;
      --teal:     #0EA5E9;
      --green:    #10B981;
      --white:    #FFFFFF;
      --gray-50:  #F8FAFC;
      --gray-100: #F1F5F9;
      --gray-200: #E2E8F0;
      --gray-400: #94A3B8;
      --gray-600: #475569;
      --gray-800: #1E293B;
      --shadow-sm: 0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.05);
      --shadow-md: 0 4px 16px rgba(0,0,0,.1);
      --shadow-lg: 0 10px 40px rgba(0,0,0,.12);
      --radius-sm: 8px;
      --radius-md: 14px;
      --radius-lg: 20px;
      --radius-xl: 28px;
    }

    /* ── Layout Helpers ── */
    .container { max-width: 1160px; margin: 0 auto; padding: 0 24px; }
    .section { padding: 80px 0; }
    .section-label {
      font-size: 13px; font-weight: 700; letter-spacing: .12em;
      text-transform: uppercase; color: var(--blue); margin-bottom: 12px;
    }
    .section-title {
      font-size: clamp(28px, 4vw, 42px); font-weight: 800;
      color: var(--gray-800); line-height: 1.2; margin-bottom: 16px;
    }
    .section-subtitle {
      font-size: 18px; color: var(--gray-600); max-width: 560px; line-height: 1.7;
    }

    /* ─────────────────────────────────────────
       HEADER
    ───────────────────────────────────────── */
    .header {
      position: sticky; top: 0; z-index: 100;
      background: rgba(255,255,255,.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
    }
    .header-inner {
      display: flex; align-items: center; justify-content: space-between;
      height: 68px;
    }
    .logo {
      display: flex; align-items: center; gap: 10px;
      font-size: 22px; font-weight: 900; color: var(--navy);
      letter-spacing: -.5px;
    }
    .logo-icon {
      width: 36px; height: 36px; border-radius: 10px;
      background: var(--navy);
      display: flex; align-items: center; justify-content: center;
    }
    .logo-icon i { color: var(--yellow); font-size: 20px; }
    .logo span.accent { color: var(--blue); }

    .nav-links {
      display: flex; align-items: center; gap: 8px; list-style: none;
    }
    .nav-links a {
      font-size: 15px; font-weight: 500; color: var(--gray-600);
      padding: 8px 14px; border-radius: var(--radius-sm);
      transition: color .2s, background .2s;
    }
    .nav-links a:hover { color: var(--navy); background: var(--gray-100); }
    .nav-links .btn-login {
      color: var(--navy); font-weight: 600;
    }
    .nav-links .btn-signup {
      background: var(--navy); color: #fff; padding: 9px 20px;
      border-radius: var(--radius-sm); font-weight: 600;
      transition: background .2s, transform .15s;
    }
    .nav-links .btn-signup:hover { background: var(--navy-mid); transform: translateY(-1px); }

    /* Hamburger */
    .hamburger {
      display: none; background: none; border: none;
      width: 40px; height: 40px; border-radius: var(--radius-sm);
      align-items: center; justify-content: center;
      color: var(--navy); font-size: 24px;
      transition: background .2s;
    }
    .hamburger:hover { background: var(--gray-100); }

    /* Mobile Drawer */
    .mobile-drawer {
      display: none;
      position: fixed; top: 0; right: -100%; width: min(320px, 85vw); height: 100vh;
      background: #fff; z-index: 200; padding: 24px;
      box-shadow: -8px 0 32px rgba(0,0,0,.18);
      transition: right .3s cubic-bezier(.25,.8,.25,1);
      flex-direction: column; gap: 8px;
    }
    .mobile-drawer.open { right: 0; }
    .mobile-drawer-header {
      display: flex; justify-content: space-between; align-items: center;
      margin-bottom: 24px;
    }
    .mobile-drawer .close-btn {
      background: none; border: none; font-size: 24px;
      color: var(--gray-600); cursor: pointer;
      width: 40px; height: 40px; display: flex; align-items: center; justify-content: center;
      border-radius: var(--radius-sm);
    }
    .mobile-drawer .close-btn:hover { background: var(--gray-100); }
    .mobile-nav-link {
      display: flex; align-items: center; gap: 12px;
      padding: 14px 16px; border-radius: var(--radius-sm);
      font-size: 16px; font-weight: 500; color: var(--gray-800);
      transition: background .15s;
    }
    .mobile-nav-link:hover { background: var(--gray-100); }
    .mobile-nav-link i { font-size: 20px; color: var(--blue); }
    .mobile-nav-divider { height: 1px; background: var(--gray-200); margin: 8px 0; }
    .mobile-nav-cta {
      margin-top: 16px; padding: 14px; border-radius: var(--radius-sm);
      background: var(--navy); color: #fff; font-weight: 700; font-size: 16px;
      text-align: center; transition: background .2s;
    }
    .mobile-nav-cta:hover { background: var(--navy-mid); }
    .drawer-overlay {
      display: none; position: fixed; inset: 0;
      background: rgba(0,0,0,.4); z-index: 190;
    }
    .drawer-overlay.open { display: block; }

    /* ─────────────────────────────────────────
       HERO
    ───────────────────────────────────────── */
    .hero {
      background: linear-gradient(135deg, var(--navy) 0%, #2a1f8f 55%, #1a55d4 100%);
      padding: 80px 0 0;
      overflow: hidden;
      position: relative;
    }
    .hero::before {
      content: '';
      position: absolute; inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Ccircle cx='30' cy='30' r='20'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
      pointer-events: none;
    }
    .hero-content {
      position: relative; z-index: 1;
      display: grid; grid-template-columns: 1fr 1fr; gap: 48px; align-items: end;
    }
    .hero-left { padding-bottom: 60px; }
    .hero-badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: rgba(255,255,255,.12); border: 1px solid rgba(255,255,255,.2);
      border-radius: 100px; padding: 6px 16px; margin-bottom: 28px;
      font-size: 13px; font-weight: 600; color: rgba(255,255,255,.9);
    }
    .hero-badge i { color: var(--yellow); font-size: 14px; }
    .hero-title {
      font-size: clamp(36px, 5vw, 60px); font-weight: 900;
      color: #fff; line-height: 1.1; margin-bottom: 20px; letter-spacing: -.5px;
    }
    .hero-title .highlight {
      color: var(--yellow);
      position: relative;
    }
    .hero-subtitle {
      font-size: 18px; color: rgba(255,255,255,.8); line-height: 1.7;
      margin-bottom: 36px; max-width: 500px;
    }
    .hero-actions { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 40px; }
    .btn-primary {
      display: inline-flex; align-items: center; gap: 8px;
      background: var(--yellow); color: var(--navy);
      font-weight: 700; font-size: 16px;
      padding: 14px 28px; border-radius: var(--radius-sm);
      transition: background .2s, transform .15s, box-shadow .2s;
      box-shadow: 0 4px 16px rgba(255,217,48,.35);
    }
    .btn-primary:hover { background: var(--yellow-dk); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(255,217,48,.4); }
    .btn-secondary {
      display: inline-flex; align-items: center; gap: 8px;
      background: rgba(255,255,255,.12); color: #fff;
      font-weight: 600; font-size: 16px;
      padding: 14px 28px; border-radius: var(--radius-sm);
      border: 1px solid rgba(255,255,255,.25);
      transition: background .2s, transform .15s;
    }
    .btn-secondary:hover { background: rgba(255,255,255,.2); transform: translateY(-2px); }
    .hero-trust {
      display: flex; align-items: center; gap: 16px;
      padding: 14px 20px; background: rgba(255,255,255,.08);
      border-radius: var(--radius-sm); border: 1px solid rgba(255,255,255,.12);
      width: fit-content;
    }
    .hero-trust-avatars { display: flex; }
    .hero-trust-avatars .av {
      width: 32px; height: 32px; border-radius: 50%;
      border: 2px solid rgba(255,255,255,.6);
      overflow: hidden; margin-left: -8px;
      background: linear-gradient(135deg, #60a5fa, #a78bfa);
      display: flex; align-items: center; justify-content: center;
      font-size: 12px; font-weight: 700; color: #fff;
    }
    .hero-trust-avatars .av:first-child { margin-left: 0; }
    .av.av2 { background: linear-gradient(135deg, #34d399, #059669); }
    .av.av3 { background: linear-gradient(135deg, #fbbf24, #d97706); }
    .av.av4 { background: linear-gradient(135deg, #f87171, #dc2626); }
    .hero-trust-text { font-size: 13px; color: rgba(255,255,255,.85); }
    .hero-trust-text strong { color: #fff; font-weight: 700; }

    /* Hero Illustration Panel */
    .hero-right {
      display: flex; justify-content: flex-end; align-items: flex-end;
    }
    .hero-card-stack {
      position: relative; width: 100%; max-width: 460px;
      padding-bottom: 40px;
    }
    .doctor-card {
      background: #fff; border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg); padding: 24px;
      position: relative; z-index: 2;
    }
    .doctor-card-header { display: flex; align-items: center; gap: 16px; margin-bottom: 16px; }
    .doctor-avatar {
      width: 56px; height: 56px; border-radius: 14px;
      background: linear-gradient(135deg, #bfdbfe, #3b82f6);
      display: flex; align-items: center; justify-content: center;
      font-size: 24px; flex-shrink: 0;
    }
    .doctor-name { font-size: 17px; font-weight: 700; color: var(--gray-800); }
    .doctor-spec { font-size: 13px; color: var(--blue); font-weight: 500; }
    .doctor-rating { display: flex; align-items: center; gap: 4px; margin-top: 2px; }
    .doctor-rating i { color: var(--yellow-dk); font-size: 13px; }
    .doctor-rating span { font-size: 12px; color: var(--gray-600); font-weight: 500; }
    .doctor-slots {
      display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 16px;
    }
    .slot {
      padding: 6px 12px; background: var(--gray-100);
      border-radius: 6px; font-size: 13px; font-weight: 500; color: var(--gray-600);
      border: 1px solid var(--gray-200);
      transition: background .15s, color .15s, border-color .15s;
      cursor: pointer;
    }
    .slot:hover, .slot.active {
      background: #EFF6FF; color: var(--blue); border-color: #BFDBFE;
    }
    .slot.today { background: #ECFDF5; color: var(--green); border-color: #A7F3D0; }
    .book-btn {
      width: 100%; padding: 12px; background: var(--navy);
      color: #fff; font-weight: 700; font-size: 15px;
      border-radius: var(--radius-sm); transition: background .2s, transform .15s;
    }
    .book-btn:hover { background: var(--navy-mid); transform: translateY(-1px); }
    .floating-badge {
      position: absolute; background: #fff; border-radius: 12px;
      box-shadow: var(--shadow-md); padding: 10px 14px;
      display: flex; align-items: center; gap: 10px;
      animation: float 4s ease-in-out infinite;
    }
    .floating-badge i { font-size: 22px; }
    .fb-confirm {
      bottom: 0; left: -40px; z-index: 3;
      animation-delay: 0s;
    }
    .fb-confirm i { color: var(--green); }
    .fb-confirm .fb-text strong { display: block; font-size: 13px; font-weight: 700; color: var(--gray-800); }
    .fb-confirm .fb-text span { font-size: 11px; color: var(--gray-600); }
    @keyframes float {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(-8px); }
    }

    /* ─────────────────────────────────────────
       STATS BAR
    ───────────────────────────────────────── */
    .stats-bar {
      background: var(--yellow);
      padding: 28px 0;
    }
    .stats-inner {
      display: grid; grid-template-columns: repeat(4, 1fr);
      gap: 16px; text-align: center;
    }
    .stat-item { padding: 8px; }
    .stat-value {
      font-size: clamp(26px, 3.5vw, 38px); font-weight: 900;
      color: var(--navy); letter-spacing: -.5px; line-height: 1.1;
    }
    .stat-label {
      font-size: 14px; font-weight: 600; color: var(--navy);
      opacity: .75; margin-top: 4px;
    }

    /* ─────────────────────────────────────────
       SEARCH SECTION
    ───────────────────────────────────────── */
    .search-section {
      background: var(--gray-50);
      padding: 60px 0;
    }
    .search-card {
      background: #fff; border-radius: var(--radius-xl);
      box-shadow: var(--shadow-lg);
      padding: 40px 40px 36px;
      max-width: 900px; margin: 0 auto;
    }
    .search-card-header { text-align: center; margin-bottom: 32px; }
    .search-card-header h2 {
      font-size: 26px; font-weight: 800; color: var(--gray-800); margin-bottom: 8px;
    }
    .search-card-header p { color: var(--gray-600); font-size: 15px; }
    .search-form { display: flex; flex-direction: column; gap: 16px; }
    .search-fields {
      display: grid; grid-template-columns: 2fr 1.5fr 1.5fr; gap: 12px;
    }
    .field-wrap { position: relative; }
    .field-wrap label {
      display: block; font-size: 12px; font-weight: 600;
      color: var(--gray-600); margin-bottom: 6px; text-transform: uppercase; letter-spacing: .06em;
    }
    .field-wrap .field-icon {
      position: absolute; left: 14px; top: 50%; transform: translateY(-50%);
      color: var(--gray-400); font-size: 18px; pointer-events: none;
    }
    .field-input {
      width: 100%; padding: 13px 14px 13px 42px;
      border: 2px solid var(--gray-200); border-radius: var(--radius-sm);
      font-size: 15px; font-family: inherit; color: var(--gray-800);
      background: var(--gray-50);
      transition: border-color .2s, box-shadow .2s, background .2s;
      appearance: none;
    }
    .field-input:focus {
      outline: none; border-color: var(--blue);
      box-shadow: 0 0 0 3px rgba(37,99,235,.12);
      background: #fff;
    }
    .field-input::placeholder { color: var(--gray-400); }

    /* Autocomplete Dropdown */
    .autocomplete-dropdown {
      position: absolute; top: calc(100% + 6px); left: 0; right: 0;
      background: #fff; border: 2px solid var(--blue);
      border-radius: var(--radius-sm); box-shadow: var(--shadow-lg);
      z-index: 50; overflow: hidden;
      opacity: 0; visibility: hidden; transform: translateY(-6px);
      transition: opacity .2s, transform .2s, visibility .2s;
    }
    .autocomplete-dropdown.open {
      opacity: 1; visibility: visible; transform: translateY(0);
    }
    .dropdown-section-label {
      padding: 10px 14px 4px;
      font-size: 11px; font-weight: 700; color: var(--gray-400);
      text-transform: uppercase; letter-spacing: .08em;
    }
    .dropdown-item {
      display: flex; align-items: center; gap: 12px;
      padding: 11px 14px; cursor: pointer;
      transition: background .12s;
    }
    .dropdown-item:hover, .dropdown-item.highlighted {
      background: #EFF6FF;
    }
    .dropdown-item i { color: var(--blue); font-size: 18px; flex-shrink: 0; }
    .dropdown-item-name { font-size: 14px; font-weight: 600; color: var(--gray-800); }
    .dropdown-item-desc { font-size: 12px; color: var(--gray-600); }
    .dropdown-item .highlight-text { color: var(--blue); }

    .geo-btn {
      position: absolute; right: 10px; top: 50%; transform: translateY(-50%);
      background: none; border: none; color: var(--blue);
      font-size: 18px; cursor: pointer; padding: 4px;
      transition: color .2s;
    }
    .geo-btn:hover { color: var(--navy); }
    #location-input { padding-right: 38px; }

    .search-submit-row {
      display: flex; justify-content: center;
    }
    .search-submit-btn {
      display: flex; align-items: center; gap: 10px;
      background: var(--navy); color: #fff;
      font-size: 17px; font-weight: 700;
      padding: 15px 48px; border-radius: var(--radius-sm);
      box-shadow: 0 4px 16px rgba(27,20,100,.25);
      transition: background .2s, transform .15s, box-shadow .2s;
    }
    .search-submit-btn:hover {
      background: var(--navy-mid); transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(27,20,100,.3);
    }
    .search-submit-btn i { font-size: 20px; }

    /* ─────────────────────────────────────────
       POPULAR SPECIALTIES
    ───────────────────────────────────────── */
    .specialties-section { background: #fff; }
    .specialties-header { text-align: center; margin-bottom: 48px; }
    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 16px;
    }
    .specialty-card {
      background: var(--gray-50); border: 2px solid var(--gray-100);
      border-radius: var(--radius-md); padding: 28px 16px 24px;
      text-align: center; cursor: pointer;
      transition: border-color .2s, box-shadow .2s, transform .2s, background .2s;
      position: relative; overflow: hidden;
    }
    .specialty-card::before {
      content: ''; position: absolute; inset: 0;
      background: linear-gradient(135deg, rgba(37,99,235,.05) 0%, rgba(14,165,233,.05) 100%);
      opacity: 0; transition: opacity .2s;
    }
    .specialty-card:hover {
      border-color: var(--blue); box-shadow: var(--shadow-md);
      transform: translateY(-4px); background: #fff;
    }
    .specialty-card:hover::before { opacity: 1; }
    .specialty-icon-wrap {
      width: 64px; height: 64px; border-radius: 18px;
      display: flex; align-items: center; justify-content: center;
      margin: 0 auto 16px; font-size: 30px;
      transition: transform .2s;
    }
    .specialty-card:hover .specialty-icon-wrap { transform: scale(1.08); }
    .specialty-name {
      font-size: 14px; font-weight: 700; color: var(--gray-800); margin-bottom: 6px;
    }
    .specialty-desc { font-size: 12px; color: var(--gray-600); line-height: 1.4; }
    .specialty-arrow {
      display: flex; align-items: center; justify-content: center;
      margin-top: 12px; color: var(--blue); opacity: 0;
      font-size: 14px; transition: opacity .2s, transform .2s;
    }
    .specialty-card:hover .specialty-arrow { opacity: 1; transform: translateX(3px); }

    /* Color variants */
    .spec-1 .specialty-icon-wrap { background: #EFF6FF; color: #2563EB; }
    .spec-2 .specialty-icon-wrap { background: #ECFDF5; color: #059669; }
    .spec-3 .specialty-icon-wrap { background: #FFF7ED; color: #EA580C; }
    .spec-4 .specialty-icon-wrap { background: #FAF5FF; color: #7C3AED; }
    .spec-5 .specialty-icon-wrap { background: #FFFBEB; color: #D97706; }
    .spec-6 .specialty-icon-wrap { background: #FFF1F2; color: #E11D48; }

    /* ─────────────────────────────────────────
       HOW IT WORKS
    ───────────────────────────────────────── */
    .how-section { background: var(--gray-50); }
    .how-header { text-align: center; margin-bottom: 56px; }
    .how-steps {
      display: grid; grid-template-columns: repeat(3, 1fr);
      gap: 32px; position: relative;
    }
    .how-steps::before {
      content: '';
      position: absolute; top: 36px; left: calc(16.66% + 20px); right: calc(16.66% + 20px);
      height: 2px;
      background: repeating-linear-gradient(90deg, var(--blue) 0, var(--blue) 8px, transparent 8px, transparent 20px);
      z-index: 0;
    }
    .how-step {
      background: #fff; border-radius: var(--radius-lg);
      padding: 36px 28px; text-align: center;
      box-shadow: var(--shadow-sm);
      border: 1px solid var(--gray-200);
      transition: box-shadow .2s, transform .2s;
      position: relative; z-index: 1;
    }
    .how-step:hover { box-shadow: var(--shadow-md); transform: translateY(-3px); }
    .step-number-wrap { position: relative; display: inline-block; margin-bottom: 20px; }
    .step-circle {
      width: 72px; height: 72px; border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      margin: 0 auto; font-size: 32px; position: relative;
    }
    .step-badge {
      position: absolute; top: -4px; right: -4px;
      width: 24px; height: 24px; border-radius: 50%;
      background: var(--navy); color: #fff;
      font-size: 11px; font-weight: 800;
      display: flex; align-items: center; justify-content: center;
      border: 2px solid #fff;
    }
    .step-1 .step-circle { background: #EFF6FF; color: var(--blue); }
    .step-2 .step-circle { background: #ECFDF5; color: var(--green); }
    .step-3 .step-circle { background: #FFF7ED; color: #EA580C; }
    .how-step h3 { font-size: 18px; font-weight: 700; color: var(--gray-800); margin-bottom: 12px; }
    .how-step p { font-size: 14px; color: var(--gray-600); line-height: 1.65; }

    /* ─────────────────────────────────────────
       TESTIMONIALS
    ───────────────────────────────────────── */
    .testimonials-section { background: #fff; }
    .testimonials-header { text-align: center; margin-bottom: 48px; }
    .testimonials-grid {
      display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;
    }
    .testimonial-card {
      background: var(--gray-50); border-radius: var(--radius-lg);
      padding: 32px 28px;
      border: 1px solid var(--gray-200);
      transition: box-shadow .2s, transform .2s, border-color .2s;
      display: flex; flex-direction: column; gap: 16px;
    }
    .testimonial-card:hover {
      box-shadow: var(--shadow-md); transform: translateY(-3px); border-color: var(--gray-300);
    }
    .testimonial-stars { display: flex; gap: 3px; }
    .testimonial-stars i { color: var(--yellow-dk); font-size: 15px; }
    .testimonial-quote { font-size: 15px; color: var(--gray-700); line-height: 1.7; flex: 1; }
    .testimonial-quote::before { content: '\201C'; color: var(--blue); font-size: 28px; line-height: 1; display: block; margin-bottom: 4px; }
    .testimonial-author { display: flex; align-items: center; gap: 12px; }
    .author-avatar {
      width: 44px; height: 44px; border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: 16px; font-weight: 700; color: #fff; flex-shrink: 0;
    }
    .av-blue   { background: linear-gradient(135deg, #60a5fa, #2563eb); }
    .av-green  { background: linear-gradient(135deg, #34d399, #059669); }
    .av-orange { background: linear-gradient(135deg, #fbbf24, #d97706); }
    .author-name { font-weight: 700; font-size: 14px; color: var(--gray-800); }
    .author-loc { font-size: 12px; color: var(--gray-500); }
    .verified-badge {
      display: inline-flex; align-items: center; gap: 4px;
      background: #ECFDF5; color: var(--green);
      font-size: 11px; font-weight: 600; border-radius: 100px;
      padding: 3px 10px; margin-top: 4px; align-self: flex-start;
    }
    .verified-badge i { font-size: 12px; }

    /* ─────────────────────────────────────────
       MOBILE APP PROMO
    ───────────────────────────────────────── */
    .app-promo {
      background: linear-gradient(135deg, var(--navy) 0%, #1a55d4 100%);
      padding: 80px 0;
      overflow: hidden; position: relative;
    }
    .app-promo::after {
      content: '';
      position: absolute; right: -80px; top: -80px;
      width: 500px; height: 500px; border-radius: 50%;
      background: rgba(255,255,255,.04); pointer-events: none;
    }
    .app-promo-inner {
      display: grid; grid-template-columns: 1fr 1fr;
      gap: 60px; align-items: center;
    }
    .app-promo-left { position: relative; z-index: 1; }
    .app-promo-tag {
      display: inline-flex; align-items: center; gap: 6px;
      background: rgba(255,255,255,.12); border: 1px solid rgba(255,255,255,.2);
      border-radius: 100px; padding: 5px 14px; margin-bottom: 20px;
      font-size: 12px; font-weight: 600; color: rgba(255,255,255,.85);
    }
    .app-promo-tag i { color: var(--yellow); }
    .app-promo h2 {
      font-size: clamp(28px, 4vw, 44px); font-weight: 900;
      color: #fff; line-height: 1.15; margin-bottom: 16px;
    }
    .app-promo p {
      font-size: 17px; color: rgba(255,255,255,.8); line-height: 1.7;
      margin-bottom: 32px;
    }
    .app-features { display: flex; flex-direction: column; gap: 12px; margin-bottom: 36px; }
    .app-feature {
      display: flex; align-items: center; gap: 12px;
      font-size: 14px; color: rgba(255,255,255,.9); font-weight: 500;
    }
    .app-feature i { color: var(--yellow); font-size: 18px; flex-shrink: 0; }
    .store-btns { display: flex; gap: 12px; flex-wrap: wrap; }
    .store-btn {
      display: flex; align-items: center; gap: 12px;
      background: rgba(255,255,255,.12); border: 1px solid rgba(255,255,255,.25);
      border-radius: var(--radius-sm); padding: 12px 20px;
      color: #fff; transition: background .2s, transform .15s;
    }
    .store-btn:hover { background: rgba(255,255,255,.2); transform: translateY(-2px); }
    .store-btn i { font-size: 26px; }
    .store-btn-text { font-size: 10px; color: rgba(255,255,255,.7); text-transform: uppercase; letter-spacing: .06em; }
    .store-btn-name { font-size: 16px; font-weight: 700; display: block; }

    /* Phone Mockup */
    .app-promo-right {
      display: flex; justify-content: center; align-items: flex-end;
      position: relative; z-index: 1;
    }
    .phone-mockup {
      width: 260px; background: #fff;
      border-radius: 32px; overflow: hidden;
      box-shadow: 0 24px 60px rgba(0,0,0,.35);
      position: relative;
    }
    .phone-notch {
      position: absolute; top: 12px; left: 50%; transform: translateX(-50%);
      width: 100px; height: 24px; background: rgba(0,0,0,.85);
      border-radius: 100px; z-index: 5;
    }
    .phone-screen {
      background: #fff; padding: 52px 16px 24px;
      min-height: 460px;
    }
    .phone-header {
      display: flex; align-items: center; justify-content: space-between;
      margin-bottom: 16px;
    }
    .phone-logo { font-size: 14px; font-weight: 900; color: var(--navy); }
    .phone-logo span { color: var(--blue); }
    .phone-section-title { font-size: 13px; font-weight: 700; color: var(--gray-800); margin-bottom: 10px; }
    .phone-search-bar {
      background: var(--gray-100); border-radius: 10px;
      padding: 10px 12px; display: flex; align-items: center; gap: 8px;
      margin-bottom: 16px;
    }
    .phone-search-bar i { color: var(--gray-400); font-size: 16px; }
    .phone-search-bar span { font-size: 12px; color: var(--gray-400); }
    .phone-doc-card {
      background: var(--gray-50); border-radius: 12px; padding: 12px;
      margin-bottom: 8px; display: flex; align-items: center; gap: 10px;
    }
    .phone-doc-av {
      width: 40px; height: 40px; border-radius: 10px;
      background: linear-gradient(135deg, #bfdbfe, #3b82f6);
      display: flex; align-items: center; justify-content: center;
      font-size: 18px; flex-shrink: 0;
    }
    .phone-doc-name { font-size: 12px; font-weight: 700; color: var(--gray-800); }
    .phone-doc-spec { font-size: 11px; color: var(--blue); font-weight: 500; }
    .phone-doc-slot {
      margin-left: auto; background: #ECFDF5;
      color: var(--green); font-size: 10px; font-weight: 700;
      padding: 4px 8px; border-radius: 6px; flex-shrink: 0;
    }
    .phone-bottom-nav {
      display: flex; justify-content: space-around; align-items: center;
      padding: 12px 0; border-top: 1px solid var(--gray-200); margin-top: 8px;
    }
    .phone-nav-item {
      display: flex; flex-direction: column; align-items: center; gap: 2px;
    }
    .phone-nav-item i { font-size: 18px; color: var(--gray-400); }
    .phone-nav-item.active i { color: var(--navy); }
    .phone-nav-item span { font-size: 9px; color: var(--gray-400); font-weight: 500; }
    .phone-nav-item.active span { color: var(--navy); font-weight: 700; }

    /* ─────────────────────────────────────────
       FOOTER
    ───────────────────────────────────────── */
    .footer {
      background: var(--gray-800); color: rgba(255,255,255,.75);
      padding: 64px 0 32px;
    }
    .footer-grid {
      display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
      gap: 40px; margin-bottom: 48px;
    }
    .footer-brand .logo { color: #fff; margin-bottom: 14px; }
    .footer-brand .logo-icon { background: rgba(255,255,255,.1); }
    .footer-brand p { font-size: 14px; line-height: 1.7; color: rgba(255,255,255,.6); max-width: 280px; }
    .footer-tagline {
      margin-top: 16px; display: inline-flex; align-items: center; gap: 8px;
      background: rgba(255,217,48,.12); border: 1px solid rgba(255,217,48,.25);
      border-radius: 100px; padding: 5px 12px;
      font-size: 12px; font-weight: 600; color: var(--yellow);
    }
    .footer-tagline i { font-size: 13px; }
    .footer-col h4 {
      font-size: 12px; font-weight: 700; color: #fff;
      text-transform: uppercase; letter-spacing: .1em; margin-bottom: 16px;
    }
    .footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 10px; }
    .footer-col a {
      font-size: 14px; color: rgba(255,255,255,.6);
      transition: color .15s;
    }
    .footer-col a:hover { color: #fff; }
    .footer-divider { height: 1px; background: rgba(255,255,255,.1); margin-bottom: 28px; }
    .footer-bottom {
      display: flex; justify-content: space-between; align-items: center;
      flex-wrap: wrap; gap: 12px;
    }
    .footer-copy { font-size: 13px; color: rgba(255,255,255,.45); }
    .footer-copy strong { color: var(--yellow); font-weight: 600; }
    .footer-social { display: flex; gap: 8px; }
    .social-btn {
      width: 36px; height: 36px; border-radius: 8px;
      background: rgba(255,255,255,.08); display: flex; align-items: center; justify-content: center;
      color: rgba(255,255,255,.6); font-size: 17px;
      transition: background .15s, color .15s;
    }
    .social-btn:hover { background: rgba(255,255,255,.15); color: #fff; }

    /* ─────────────────────────────────────────
       RESPONSIVE
    ───────────────────────────────────────── */
    @media (max-width: 1024px) {
      .specialties-grid { grid-template-columns: repeat(3, 1fr); }
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: 1 / -1; }
    }

    @media (max-width: 768px) {
      .section { padding: 56px 0; }

      /* Header */
      .nav-links { display: none; }
      .hamburger { display: flex; }

      /* Hero */
      .hero-content { grid-template-columns: 1fr; }
      .hero-right { display: none; }
      .hero { padding: 56px 0 56px; }
      .hero-left { padding-bottom: 0; }

      /* Stats */
      .stats-inner { grid-template-columns: repeat(2, 1fr); }

      /* Search */
      .search-card { padding: 24px 20px; }
      .search-fields { grid-template-columns: 1fr; }

      /* How it works */
      .how-steps { grid-template-columns: 1fr; }
      .how-steps::before { display: none; }

      /* Specialties */
      .specialties-grid { grid-template-columns: repeat(2, 1fr); }

      /* Testimonials */
      .testimonials-grid { grid-template-columns: 1fr; }

      /* App promo */
      .app-promo-inner { grid-template-columns: 1fr; }
      .app-promo-right { display: none; }

      /* Footer */
      .footer-grid { grid-template-columns: 1fr 1fr; }
      .footer-brand { grid-column: 1 / -1; }
      .footer-bottom { flex-direction: column; text-align: center; }
    }

    @media (max-width: 480px) {
      .hero-actions { flex-direction: column; }
      .btn-primary, .btn-secondary { justify-content: center; }
      .stats-inner { grid-template-columns: 1fr 1fr; gap: 0; }
      .stat-item { padding: 16px 8px; border-right: 1px solid rgba(27,20,100,.12); border-bottom: 1px solid rgba(27,20,100,.12); }
      .stat-item:nth-child(even) { border-right: none; }
      .stat-item:nth-last-child(-n+2) { border-bottom: none; }
      .specialties-grid { grid-template-columns: repeat(2, 1fr); }
      .store-btns { flex-direction: column; }
    }

    /* Micro-interactions */
    .specialty-card:active { transform: translateY(-2px) scale(.98); }
    .btn-primary:active { transform: scale(.97); }
    .search-submit-btn:active { transform: scale(.98); }
  </style>
</head>
<body>

  <!-- ─── DRAWER OVERLAY ─── -->
  <div class="drawer-overlay" id="drawerOverlay" onclick="closeDrawer()"></div>

  <!-- ─── MOBILE DRAWER ─── -->
  <nav class="mobile-drawer" id="mobileDrawer" role="navigation" aria-label="Mobile Navigation">
    <div class="mobile-drawer-header">
      <div class="logo">
        <div class="logo-icon"><i class="ri-heart-pulse-line"></i></div>
        Med<span class="accent">Book</span>
      </div>
      <button class="close-btn" onclick="closeDrawer()" aria-label="Close menu">
        <i class="ri-close-line"></i>
      </button>
    </div>
    <a class="mobile-nav-link" href="#specialties"><i class="ri-stethoscope-line"></i> Browse Specialties</a>
    <a class="mobile-nav-link" href="#how-it-works"><i class="ri-question-line"></i> How It Works</a>
    <div class="mobile-nav-divider"></div>
    <a class="mobile-nav-link" href="#"><i class="ri-user-line"></i> Log In</a>
    <a class="mobile-nav-cta" href="#">Sign Up — It's Free</a>
  </nav>

  <!-- ─── HEADER ─── -->
  <header class="header" role="banner">
    <div class="container">
      <div class="header-inner">
        <a class="logo" href="index.html" aria-label="MedBook Home">
          <div class="logo-icon" aria-hidden="true"><i class="ri-heart-pulse-line"></i></div>
          Med<span class="accent">Book</span>
        </a>
        <ul class="nav-links" role="list">
          <li><a href="#specialties">Browse</a></li>
          <li><a href="#how-it-works">Help</a></li>
          <li><a href="#" class="btn-login">Log In</a></li>
          <li><a href="#" class="btn-signup">Sign Up</a></li>
        </ul>
        <button class="hamburger" id="hamburgerBtn" aria-label="Open navigation menu" aria-expanded="false" onclick="openDrawer()">
          <i class="ri-menu-line"></i>
        </button>
      </div>
    </div>
  </header>

  <!-- ─── HERO ─── -->
  <section class="hero" aria-labelledby="hero-title">
    <div class="container">
      <div class="hero-content">
        <div class="hero-left">
          <div class="hero-badge">
            <i class="ri-shield-check-line"></i>
            Trusted by 4.8M+ patients nationwide
          </div>
          <h1 class="hero-title" id="hero-title">
            Find and book the<br/><span class="highlight">care you need</span>
          </h1>
          <p class="hero-subtitle">
            Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.
          </p>
          <div class="hero-actions">
            <a href="#search" class="btn-primary">
              <i class="ri-search-2-line"></i> Find a Doctor
            </a>
            <a href="#specialties" class="btn-secondary">
              <i class="ri-stethoscope-line"></i> Browse Specialties
            </a>
          </div>
          <div class="hero-trust" aria-label="Recent patient bookings">
            <div class="hero-trust-avatars" aria-hidden="true">
              <div class="av">P</div>
              <div class="av av2">J</div>
              <div class="av av3">L</div>
              <div class="av av4">M</div>
            </div>
            <p class="hero-trust-text"><strong>2,400+ patients</strong> booked today</p>
          </div>
        </div>
        <div class="hero-right" aria-hidden="true">
          <div class="hero-card-stack">
            <div class="doctor-card">
              <div class="doctor-card-header">
                <div class="doctor-avatar" aria-hidden="true">👩‍⚕️</div>
                <div>
                  <div class="doctor-name">Dr. Sarah Chen</div>
                  <div class="doctor-spec">Primary Care Physician</div>
                  <div class="doctor-rating">
                    <i class="ri-star-fill"></i><i class="ri-star-fill"></i><i class="ri-star-fill"></i><i class="ri-star-fill"></i><i class="ri-star-fill"></i>
                    <span>5.0 · 312 reviews</span>
                  </div>
                </div>
              </div>
              <p style="font-size:12px;color:var(--gray-600);margin-bottom:12px;font-weight:600;text-transform:uppercase;letter-spacing:.06em;">Available Today</p>
              <div class="doctor-slots">
                <span class="slot today">9:00 AM</span>
                <span class="slot active">11:30 AM</span>
                <span class="slot">2:00 PM</span>
                <span class="slot">4:15 PM</span>
              </div>
              <button class="book-btn">Book Appointment</button>
            </div>
            <div class="floating-badge fb-confirm">
              <i class="ri-checkbox-circle-fill"></i>
              <div class="fb-text">
                <strong>Appointment Confirmed!</strong>
                <span>Today at 11:30 AM · Dr. Chen</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- ─── STATS BAR ─── -->
  <section class="stats-bar" aria-label="Platform statistics">
    <div class="container">
      <div class="stats-inner">
        <div class="stat-item">
          <div class="stat-value">4.8M+</div>
          <div class="stat-label">Verified patient reviews</div>
        </div>
        <div class="stat-item">
          <div class="stat-value">12,000+</div>
          <div class="stat-label">Healthcare providers</div>
        </div>
        <div class="stat-item">
          <div class="stat-value">Same-day</div>
          <div class="stat-label">Appointments available daily</div>
        </div>
        <div class="stat-item">
          <div class="stat-value">100% Free</div>
          <div class="stat-label">For patients — always</div>
        </div>
      </div>
    </div>
  </section>

  <!-- ─── SEARCH ─── -->
  <section class="search-section" id="search" aria-labelledby="search-heading">
    <div class="container">
      <div class="search-card">
        <div class="search-card-header">
          <h2 id="search-heading">Find the right doctor for you</h2>
          <p>Search by specialty, condition, doctor name, and location — with your insurance covered.</p>
        </div>
        <form class="search-form" onsubmit="handleSearch(event)" role="search" aria-label="Doctor search form">
          <div class="search-fields">

            <!-- Specialty / Condition / Doctor -->
            <div class="field-wrap" style="position:relative;">
              <label for="specialty-input">Specialty, Condition or Doctor</label>
              <i class="ri-stethoscope-line field-icon" aria-hidden="true"></i>
              <input
                type="text"
                id="specialty-input"
                class="field-input"
                placeholder="Search by condition, specialty, or doctor name"
                autocomplete="off"
                aria-autocomplete="list"
                aria-controls="specialty-dropdown"
                aria-expanded="false"
                oninput="handleSpecialtyInput(this)"
                onfocus="handleSpecialtyFocus()"
                onblur="closeDropdown('specialty-dropdown')"
              />
              <div class="autocomplete-dropdown" id="specialty-dropdown" role="listbox" aria-label="Suggestions">
                <div class="dropdown-section-label">Specialties</div>
                <div class="dropdown-item" role="option" onmousedown="selectDropdownItem('specialty-input', 'Primary Care', 'specialty-dropdown')">
                  <i class="ri-heart-pulse-line" aria-hidden="true"></i>
                  <div><div class="dropdown-item-name">Primary Care</div><div class="dropdown-item-desc">Annual checkups, sick visits</div></div>
                </div>
                <div class="dropdown-item" role="option" onmousedown="selectDropdownItem('specialty-input', 'Dentist', 'specialty-dropdown')">
                  <i class="ri-tooth-line" aria-hidden="true"></i>
                  <div><div class="dropdown-item-name">Dentist</div><div class="dropdown-item-desc">Cleanings, fillings, oral health</div></div>
                </div>
                <div class="dropdown-item" role="option" onmousedown="selectDropdownItem('specialty-input', 'Dermatologist', 'specialty-dropdown')">
                  <i class="ri-microscope-line" aria-hidden="true"></i>
                  <div><div class="dropdown-item-name">Dermatologist</div><div class="dropdown-item-desc">Skin conditions, acne, cosmetic</div></div>
                </div>
                <div class="dropdown-item" role="option" onmousedown="selectDropdownItem('specialty-input', 'Psychiatrist', 'specialty-dropdown')">
                  <i class="ri-mental-health-line" aria-hidden="true"></i>
                  <div><div class="dropdown-item-name">Psychiatrist</div><div class="dropdown-item-desc">Mental health, medication management</div></div>
                </div>
                <div class="dropdown-item" role="option" onmousedown="selectDropdownItem('specialty-input', 'Eye Doctor', 'specialty-dropdown')">
                  <i class="ri-eye-line" aria-hidden="true"></i>
                  <div><div class="dropdown-item-name">Eye Doctor</div><div class="dropdown-item-desc">Vision exams, glasses prescriptions</div></div>
                </div>
                <div class="dropdown-section-label">Conditions</div>
                <div class="dropdown-item" role="option" onmousedown="selectDropdownItem('specialty-input', 'Back pain', 'specialty-dropdown')">
                  <i class="ri-health-book-line" aria-hidden="true"></i>
                  <div><div class="dropdown-item-name">Back pain</div><div class="dropdown-item-desc">Orthopedic, Physical Therapy</div></div>
                </div>
                <div class="dropdown-item" role="option" onmousedown="selectDropdownItem('specialty-input', 'Anxiety', 'specialty-dropdown')">
                  <i class="ri-brain-line" aria-hidden="true"></i>
                  <div><div class="dropdown-item-name">Anxiety</div><div class="dropdown-item-desc">Psychiatry, Counseling</div></div>
                </div>
              </div>
            </div>

            <!-- Location -->
            <div class="field-wrap">
              <label for="location-input">Location</label>
              <i class="ri-map-pin-2-line field-icon" aria-hidden="true"></i>
              <input
                type="text"
                id="location-input"
                class="field-input"
                placeholder="City, state, or zip code"
                autocomplete="off"
              />
              <button class="geo-btn" type="button" onclick="detectLocation()" title="Use my current location" aria-label="Detect my location">
                <i class="ri-crosshair-2-line"></i>
              </button>
            </div>

            <!-- Insurance -->
            <div class="field-wrap">
              <label for="insurance-select">Insurance Plan</label>
              <i class="ri-shield-check-line field-icon" aria-hidden="true"></i>
              <select id="insurance-select" class="field-input" aria-label="Select insurance plan">
                <option value="">Choose your insurance plan</option>
                <option value="aetna">Aetna</option>
                <option value="bcbs">Blue Cross Blue Shield</option>
                <option value="cigna">Cigna</option>
                <option value="united">UnitedHealthcare</option>
                <option value="humana">Humana</option>
                <option value="kaiser">Kaiser Permanente</option>
                <option value="oscar">Oscar Health</option>
                <option value="molina">Molina Healthcare</option>
                <option value="none">No Insurance / Self-pay</option>
              </select>
            </div>

          </div>
          <div class="search-submit-row">
            <button type="submit" class="search-submit-btn">
              <i class="ri-search-2-line" aria-hidden="true"></i>
              Search Doctors
            </button>
          </div>
        </form>
      </div>
    </div>
  </section>

  <!-- ─── POPULAR SPECIALTIES ─── -->
  <section class="specialties-section section" id="specialties" aria-labelledby="specialties-heading">
    <div class="container">
      <div class="specialties-header">
        <p class="section-label">Browse by Specialty</p>
        <h2 class="section-title" id="specialties-heading">Popular specialties near you</h2>
        <p class="section-subtitle">Click any specialty to instantly browse verified providers in your area.</p>
      </div>
      <div class="specialties-grid" role="list">

