  <script>
    // ── Mobile Drawer ──
    const drawer = document.getElementById('mobileDrawer');
    const overlay = document.getElementById('drawerOverlay');
    const hamburger = document.getElementById('hamburgerBtn');

    function openDrawer() {
      drawer.style.display = 'flex';
      overlay.classList.add('open');
      requestAnimationFrame(() => drawer.classList.add('open'));
      hamburger.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
    }

    function closeDrawer() {
      drawer.classList.remove('open');
      overlay.classList.remove('open');
      hamburger.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
      setTimeout(() => { drawer.style.display = ''; }, 300);
    }

    // Close drawer on Escape key
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') closeDrawer();
    });

    // ── Search Autocomplete ──
    const suggestions = [
      { type: 'specialty', name: 'Primary Care',       desc: 'Annual checkups, sick visits',      icon: 'ri-heart-pulse-line' },
      { type: 'specialty', name: 'Dentist',             desc: 'Cleanings, fillings, oral health',  icon: 'ri-tooth-line' },
      { type: 'specialty', name: 'Dermatologist',       desc: 'Skin conditions, acne, cosmetic',   icon: 'ri-microscope-line' },
      { type: 'specialty', name: 'Psychiatrist',        desc: 'Mental health, medication mgmt',    icon: 'ri-mental-health-line' },
      { type: 'specialty', name: 'Eye Doctor',          desc: 'Vision exams, prescriptions',       icon: 'ri-eye-line' },
      { type: 'specialty', name: 'Orthopedic Surgeon',  desc: 'Joint pain, fractures, sports',     icon: 'ri-run-line' },
      { type: 'condition', name: 'Back pain',           desc: 'Orthopedic, Physical Therapy',      icon: 'ri-health-book-line' },
      { type: 'condition', name: 'Anxiety',             desc: 'Psychiatry, Counseling',            icon: 'ri-brain-line' },
      { type: 'condition', name: 'Acne',                desc: 'Dermatology',                       icon: 'ri-skin-line' },
      { type: 'doctor',    name: 'Dr. Sarah Chen',      desc: 'Primary Care · ★ 5.0',              icon: 'ri-user-heart-line' },
    ];

    function handleSpecialtyInput(input) {
      const val = input.value.trim().toLowerCase();
      const dd = document.getElementById('specialty-dropdown');
      if (!val) { closeDropdown('specialty-dropdown'); return; }

      const matches = suggestions.filter(s => s.name.toLowerCase().includes(val));
      if (!matches.length) { closeDropdown('specialty-dropdown'); return; }

      const byType = {};
      matches.forEach(s => { (byType[s.type] = byType[s.type] || []).push(s); });

      const labels = { specialty: 'Specialties', condition: 'Conditions', doctor: 'Doctors' };
      let html = '';
      for (const [type, items] of Object.entries(byType)) {
        html += `<div class="dropdown-section-label">${labels[type]}</div>`;
        items.forEach(item => {
          const hi = item.name.replace(new RegExp(`(${val})`, 'gi'), '<span class="highlight-text">$1</span>');
          html += `<div class="dropdown-item" role="option" onmousedown="selectDropdownItem('specialty-input','${item.name}','specialty-dropdown')">
            <i class="${item.icon}" aria-hidden="true"></i>
            <div><div class="dropdown-item-name">${hi}</div><div class="dropdown-item-desc">${item.desc}</div></div>
          </div>`;
        });
      }
      dd.innerHTML = html;
      dd.classList.add('open');
      input.setAttribute('aria-expanded', 'true');
    }

    function handleSpecialtyFocus() {
      if (!document.getElementById('specialty-input').value) {
        document.getElementById('specialty-dropdown').classList.add('open');
      }
    }

    function closeDropdown(id) {
      setTimeout(() => {
        const dd = document.getElementById(id);
        dd.classList.remove('open');
        const input = document.getElementById('specialty-input');
        if (input) input.setAttribute('aria-expanded', 'false');
      }, 150);
    }

    function selectDropdownItem(inputId, value, dropdownId) {
      document.getElementById(inputId).value = value;
      document.getElementById(dropdownId).classList.remove('open');
    }

    // ── Geolocation ──
    function detectLocation() {
      const input = document.getElementById('location-input');
      if (!navigator.geolocation) { input.placeholder = 'Geolocation not supported'; return; }
      input.placeholder = 'Detecting location…';
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          input.value = 'Current Location';
          input.placeholder = 'City, state, or zip code';
        },
        () => {
          input.placeholder = 'Could not detect location';
          setTimeout(() => { input.placeholder = 'City, state, or zip code'; }, 2500);
        }
      );
    }

    // ── Search Submit ──
    function handleSearch(e) {
      e.preventDefault();
      const specialty = document.getElementById('specialty-input').value;
      const location  = document.getElementById('location-input').value;
      const insurance = document.getElementById('insurance-select').value;
      if (!specialty && !location) {
        document.getElementById('specialty-input').focus();
        return;
      }
      const params = new URLSearchParams();
      if (specialty) params.set('q', specialty);
      if (location)  params.set('loc', location);
      if (insurance) params.set('insurance', insurance);
      window.location.href = `search-results.html?${params.toString()}`;
    }

    // ── Specialty Card Navigation ──
    function searchSpecialty(specialty) {
      window.location.href = `search-results.html?q=${encodeURIComponent(specialty)}`;
    }

    // ── Animate stats on scroll ──
    const statValues = document.querySelectorAll('.stat-value');
    const statsBar = document.querySelector('.stats-bar');
    let statsAnimated = false;

    const statsObserver = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting && !statsAnimated) {
        statsAnimated = true;
        statValues.forEach((el) => {
          el.style.transform = 'translateY(12px)';
          el.style.opacity = '0';
          el.style.transition = 'transform .5s ease, opacity .5s ease';
          setTimeout(() => {
            el.style.transform = 'translateY(0)';
            el.style.opacity = '1';
          }, 100);
        });
      }
    }, { threshold: .3 });

    if (statsBar) statsObserver.observe(statsBar);

    // ── Stagger card reveal on scroll ──
    function addScrollReveal(selector, delay = 80) {
      const items = document.querySelectorAll(selector);
      items.forEach((el, i) => {
        el.style.opacity = '0';
        el.style.transform = 'translateY(20px)';
        el.style.transition = `opacity .45s ease ${i * delay}ms, transform .45s ease ${i * delay}ms`;
      });
      const obs = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.style.opacity = '1';
            entry.target.style.transform = 'translateY(0)';
          }
        });
      }, { threshold: .12 });
      items.forEach(el => obs.observe(el));
    }

    addScrollReveal('.specialty-card', 60);
    addScrollReveal('.how-step', 120);
    addScrollReveal('.testimonial-card', 100);
  </script>
